for(const s of ['queued','failed','retry','reconnecting'])route('offline/'+s,label(s),'Offline',()=>flowFrame('Campaign studio',`${callout(s==='reconnecting'?'Still reconnecting…':'You’re offline','Cached messages are available. New messages are saved on this phone.','warning')}${msg('Maya Ndlovu','MN','The carousel is ready for review.','10:38')}${msg('Lerato Molefe','LM','I’ll review slide two before lunch.','10:42',`<div class="delivery-state">${s==='failed'?'Not sent':s==='retry'?'Retrying the same message…':'Queued on this phone'}</div>`)}${s==='failed'?link('Retry message','offline/retry','primary full')+link('Edit draft','channel','full'):link('Preview reconnection','channel','primary full')}`,{back:'channels'}),'27 · Local outbox state, not recipient read status');
for(const s of ['template','review','unavailable','edit','created','failed'])route('channel-new/'+s,label(s),'Channels',()=>flowFrame('Create a channel',s==='template'?`<h1 class="flow-title">Start with a useful shape.</h1>${listrow('Client campaign','Brief, approvals and deliverables','channel-new/review',icon('briefcase'))}${listrow('Team forum','Plans and longer discussions','channel-new/review',icon('chat'))}`:s==='created'?result('Your channel is ready','The channel uses the people and agent access you reviewed.','channel','Open channel'):s==='failed'?result('Channel wasn’t created','Your name, template and access choices are kept. Retry safely without creating a second channel.','channel-new/review','Try again','warning'):`${input('Channel name','Olive Studio campaign')}${choose('Visibility',['Private · Invited members only','Open · Business members'])}${block('Inherited access',listrow('Lerato Molefe','Owner','settings/people',av('LM'))+listrow('Maya Ndlovu','Member','settings/people',av('MN','coral'))+listrow('Scout',s==='unavailable'?'Unavailable · Connect host or remove suggestion':'Suggested agent · Research access','agents/connect',av('S','sage')))}${s==='unavailable'?callout('Scout is unavailable','You can create the channel without an agent and add Scout later.','warning'):''}`,{back:'channels',footer:['template','created','failed'].includes(s)?'':link('Create channel','channel-new/created','primary full')}));
for(const s of ['mentions','reactions','menu','delete','attachments'])route('conversation/'+s,label(s),'Conversation controls',()=>flowFrame(label(s),s==='mentions'?`<label class="search">${icon('search')}<input placeholder="Find people or agents" aria-label="Find mention" value="Sc"></label>${listrow('Scout','Agent · In this channel','channel',av('S','sage'))}${listrow('Scott Adams','Not in channel · Review access before inviting','settings/people',av('SA'))}`:s==='reactions'?`<h1 class="flow-title">A quick response.</h1><div class="avatar-picks">${['👍','❤️','🎉','✅','🙌','💡'].map(x=>`<button data-route="channel" aria-label="React ${x}">${x}</button>`).join('')}</div>`:s==='delete'?`<h1 class="flow-title">Delete your message?</h1><p class="flow-description">The message will disappear from this conversation. Business audit retention may still apply.</p>${link('Keep message','channel','full')}${link('Delete message','channel','danger full')}`:s==='attachments'?`${listrow('Photos','Choose from this phone','profile/image',icon('image'))}${listrow('Files','Browse shared files','work/files',icon('file'))}${listrow('Camera','Take a photo','permissions/camera',icon('image'))}`:`${listrow('Reply in thread','','thread',icon('chat'))}${listrow('Add reaction','','conversation/reactions',icon('check'))}${listrow('Save for later','','channel',icon('bookmark'))}${listrow('Edit message','','channel',icon('file'))}${listrow('Delete message','','conversation/delete',icon('close'))}`,{back:'channel'}));

for(const state of ['compose','voice','voice-preview'])route('conversation/'+state,label(state),'Conversation controls',()=>flowFrame(state==='compose'?'Compose message':'Voice note',state==='compose'?`${msg('Maya Ndlovu','MN','The designs are ready for review.','10:38')}${area('Message','@Scout please check the updated brief.','compose-draft')}${link('Mention someone','conversation/mentions','text-button')}`:`<div class="voice ${state==='voice'?'recording':''}">${wave()}<strong>0:12</strong><p>${state==='voice'?'Recording preview · microphone not active':'Review before sharing with Campaign studio.'}</p></div>${state==='voice-preview'?callout('Audio preview','Playback is simulated in this design review.'):''}`,{back:'channel',footer:state==='compose'?link('Send message','channel','primary full'):link(state==='voice'?'Stop recording':'Send voice note',state==='voice'?'conversation/voice-preview':'channel','primary full')+link('Discard','channel','text-button full')}));

const coreRender=render;
const coreRoutes=['channels','channel','thread','viewer','dm','scout','forum','note','activity','business'];
function businessHome(){return `${header('Lerato Social','Your business, together','','profile')}<main class="scroll flow-scroll"><div class="roster-heading"><div><h1>Keep things moving.</h1><p>Your team, tools and business.</p></div></div><div class="business-attention">${av('D','sage')}<div><strong>One review unlocks the next step.</strong><p>Olive Studio · September journal</p></div>${link('Review','viewer','text-button')}</div>${block('People & work',listrow('Your agents','30 agents · 2 need attention','agents/roster',icon('activity'))+listrow('Discovery','Find and qualify new clients','discovery/search',icon('search'))+listrow('Blocks & templates','Repeat the work that works','blocks/catalog',icon('file')))}${block('Business controls',listrow('Credits','240 credits available','credits/balance',icon('briefcase'))+listrow('Work area','Campaign studio · 5 tabs','work/files',icon('chat'))+listrow('Settings','Account, business and this phone','settings/home',icon('more')))}</main>${nav()}`;}
render=function(){if(!FLOWS[page]&&page!=='business'){coreRender();}else{phone.classList.remove('typing');phone.innerHTML=`<div class="status"><span>9:41</span><div>${icon('signal')}${icon('battery')}</div></div>${page==='business'?businessHome():FLOWS[page].draw()}<div class="home-indicator"></div>`;}const picker=document.querySelector('#flow-picker');if(picker)picker.value=page;document.querySelector('#review-state').textContent=FLOWS[page]?`${page} · ${FLOWS[page].source}`:`${page} · Core collaboration`;gateConsent();};
function gateConsent(){if(['blocks/permissions','browser/consent','discovery/review','account/sign-up'].includes(page)){const checks=[...phone.querySelectorAll('.toggle-row input')];const action=phone.querySelector('.flow-footer .primary')||phone.querySelector('.primary.full');if(action&&checks.length)action.disabled=!checks.every(x=>x.checked);}}
function goFlow(p){if(p==='credits/paused')flowData.resumeTask=true;if(!FLOWS[p]&&!coreRoutes.includes(p))return;sheet='';typing=false;page=p;location.hash=p;render();}
const picker=document.createElement('select');picker.id='flow-picker';picker.setAttribute('aria-label','Review screen');picker.innerHTML=`<optgroup label="Core collaboration">${coreRoutes.map(r=>`<option value="${r}">${label(r)}</option>`).join('')}</optgroup>`+[...new Set(Object.values(FLOWS).map(x=>x.group))].map(g=>`<optgroup label="${g}">${Object.entries(FLOWS).filter(([,v])=>v.group===g).map(([r,v])=>`<option value="${r}">${v.group} · ${v.title}</option>`).join('')}</optgroup>`).join('');document.querySelector('.review>div').prepend(picker);picker.addEventListener('change',()=>goFlow(picker.value));
document.addEventListener('click',e=>{const target=e.target.closest('[data-route]');if(target){e.stopImmediatePropagation();if(!target.disabled)goFlow(target.dataset.route);return;}const action=e.target.closest('[data-action]')?.dataset.action;if(FLOWS[action]){e.stopImmediatePropagation();goFlow(action);return;}const remap={'huddle':'huddle/lobby','new-channel':'channel-new/template'};if(remap[action]){e.stopImmediatePropagation();goFlow(remap[action]);return;}if(action==='actions'&&FLOWS[page]){e.stopImmediatePropagation();goFlow('settings/home');return;}if(e.target.closest('[aria-label="Switch business"]')){e.stopImmediatePropagation();goFlow('switch/business');return;}const theme=e.target.closest('[data-theme-pick]');if(theme){flowData.theme=theme.dataset.themePick;phone.querySelectorAll('[data-theme-pick]').forEach(x=>x.classList.toggle('chosen',x===theme));phone.querySelector('.appearance-preview').style.background=getComputedStyle(theme.querySelector('span')).background;return;}const avatar=e.target.closest('[data-avatar]');if(avatar){flowData.avatar=avatar.dataset.avatar;render();}},true);
document.addEventListener('input',e=>{if(e.target.dataset.field&&e.target.type!=='password'){flowData[e.target.dataset.field]=e.target.value;}if(e.target.matches('[data-agent-search]'))phone.querySelectorAll('[data-agent-name]').forEach(x=>x.hidden=!x.dataset.agentName.includes(e.target.value.toLowerCase()));if(e.target.matches('[data-crop]'))phone.querySelector('.avatar-stage .avatar').style.transform=`scale(${e.target.value})`;});
document.addEventListener('change',e=>{gateConsent();if(e.target.dataset.field)flowData[e.target.dataset.field]=e.target.value;if(e.target.matches('[data-avatar-file]')){const f=e.target.files[0];if(f)goFlow(['image/jpeg','image/png','image/webp'].includes(f.type)?'profile/crop':'profile/invalid');}});
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(FLOWS[target]&&page!==target){page=target;sheet='';typing=false;render();}});
const requested=location.hash.slice(1);if(FLOWS[requested])page=requested;
document.querySelector('aside').innerHTML=`<span class="eyebrow">R15 · MANROPE · MOBILE REVIEW</span><h1>A business.<br>In your pocket.</h1><p>Open Today for work needing attention and team Updates. Open Business to explore agents, settings, credits, discovery and your work area. Use the screen picker for onboarding and recovery states.</p><ol><li>Account & device setup</li><li>Channels, agents & huddles</li><li>Settings, identity & permissions</li><li>Credits, blocks, discovery & browser</li></ol><p class="fine">Interactive design proposal. Sample data; no live payments, authentication or microphone access. Today includes Updates and Compose Note.</p><div id="review-state" class="review-footnote"></div>`;
render();
